<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import Icon from './HelmLabIcon.vue';
import Confirm from './LocalLabConfirm.vue';
import Markdown from './IssuePackageMarkdown.vue';
import {apiFetch,setActivePanelTab} from './store.js';
import {testWorkspaceIntent} from './cluster-workspace-store.mjs';
import {writeTextToClipboard} from './clipboard.js';
import {packageBytes,packageDate} from './issue-packages.mjs';
const props=defineProps({pkg:{type:Object,default:null},initialMode:{type:String,default:'report'}});
const emit=defineEmits(['imported']);
const mode=ref(props.pkg?props.initialMode:(props.initialMode==='archive'?'archive':'bundle')),reportDirty=ref(false),reportStale=ref(false),raw=ref(false),markdown=ref(''),includeNotes=ref(false),artifactNames=ref([]),sessionId=ref(''),pending=ref(''),error=ref(''),notice=ref(''),preview=ref(null),bundle=ref(null),archiveReview=ref(null),archives=ref([]),archiveResult=ref(null),fileInput=ref(null),createRepo=ref(false),newRepo=ref('runway-issue-packages');
let savedRepo='';try{savedRepo=localStorage.getItem('runwayIssuePackageArchive')||'';}catch{}
const repository=ref(savedRepo),controllers=new Set();let disposed=false;
const artifacts=computed(()=>{const unique=new Map();for(const session of props.pkg?.sessions||[])for(const evidence of session.evidence||[])if(evidence.artifact)unique.set(evidence.artifact.name,{...evidence.artifact,label:evidence.name,session:session.name,kind:evidence.kind});return [...unique.values()];});
const selectedBytes=computed(()=>artifacts.value.filter(item=>!item.omitted&&artifactNames.value.includes(item.name)).reduce((sum,item)=>sum+item.bytes,0));
const options=()=>({id:props.pkg?.id,includeNotes:includeNotes.value,artifactNames:[...artifactNames.value]});
async function request(action,fields={}){const controller=new AbortController();controllers.add(controller);const timer=setTimeout(()=>controller.abort(),90000);try{const response=await apiFetch('/api/issue-packages',{method:'POST',body:JSON.stringify({action,...fields}),signal:controller.signal});if(!response.ok)throw new Error(await response.text());return await response.json();}catch(err){if(err.name==='AbortError')throw new Error('The request timed out. Your local package is still safe.');throw err;}finally{clearTimeout(timer);controllers.delete(controller);}}
async function perform(label,fn){if(pending.value)return;pending.value=label;error.value='';notice.value='';try{await fn();}catch(err){if(!disposed)error.value=err.message;}finally{pending.value='';}}
async function report(){if(!props.pkg)return;await perform('report',async()=>{const result=await request('report',{id:props.pkg?.id,sessionId:sessionId.value,includeNotes:includeNotes.value});markdown.value=result.markdown;reportDirty.value=false;reportStale.value=false;});}
async function exportBundle(){await perform('export',async()=>{const result=await request('export',options());notice.value=`Saved ${result.filename} and ${result.reportFilename} to Downloads.`;});}
async function previewImport(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;preview.value=null;bundle.value=null;await perform('preview',async()=>{if(file.size>64*1024*1024)throw new Error('Choose a Runway package smaller than 64 MiB.');let content;try{content=JSON.parse(await file.text());}catch{throw new Error('This file is not a readable Runway issue package. Choose a .runway-issue-package.json export.');}const result=await request('import-preview',{bundle:content});bundle.value=content;preview.value=result;});}
async function importBundle(){await perform('import',async()=>{const result=await request('import',{bundle:bundle.value,reviewToken:preview.value.reviewToken,confirm:'confirm'});preview.value=null;bundle.value=null;emit('imported',result.package);});}
async function inspectArchive(){archiveReview.value=null;await perform('inspect',async()=>{archiveReview.value=await request('archive-inspect',{...options(),repository:repository.value.trim()});});}
async function backup(){await perform('backup',async()=>{archiveResult.value=await request('archive-backup',{...options(),repository:repository.value.trim(),remoteSha:archiveReview.value.remoteSha,reviewToken:archiveReview.value.reviewToken});archiveReview.value=null;try{localStorage.setItem('runwayIssuePackageArchive',repository.value.trim());}catch{}notice.value='Private backup saved. Your local package remains available.';});}
async function listArchive(){await perform('list',async()=>{const result=await request('archive-list',{repository:repository.value.trim()});archives.value=result.items||[];try{localStorage.setItem('runwayIssuePackageArchive',repository.value.trim());}catch{}});}
async function loadArchive(item){await perform('load',async()=>{const result=await request('archive-load',{repository:repository.value.trim(),sourceId:item.id});bundle.value=result.bundle;preview.value=result.preview;});}
async function makeRepo(){await perform('create-repo',async()=>{const result=await request('archive-create',{repository:newRepo.value.trim(),confirm:'confirm'});repository.value=result.repository||result.fullName||'';createRepo.value=false;notice.value='Private archive repository created. Review a backup when you are ready.';});}
async function copy(){await perform('copy',async()=>{await writeTextToClipboard(markdown.value);notice.value='Markdown copied. Ready to paste into your GitHub issue.';});}
function connect(){testWorkspaceIntent.value={view:'github'};setActivePanelTab('tests');}
watch([repository,includeNotes,artifactNames,()=>props.pkg?.revision],()=>{archiveReview.value=null;archiveResult.value=null;},{deep:true});
watch([includeNotes,sessionId,()=>props.pkg?.revision],()=>{if(mode.value==='report'){if(reportDirty.value)reportStale.value=true;else report();}});
watch(()=>props.pkg?.id,()=>{includeNotes.value=false;artifactNames.value=[];sessionId.value='';preview.value=null;bundle.value=null;archiveReview.value=null;report();});
watch(mode,value=>{if(value==='report'&&!reportDirty.value)report();});
onMounted(()=>{if(props.pkg)report();});onBeforeUnmount(()=>{disposed=true;for(const controller of controllers)controller.abort();});
</script>
<template>
<div class="package-sharing">
  <div class="ps-tabs" aria-label="Sharing format"><button v-for="item in [{id:'report',label:'GitHub report',icon:'file'},{id:'bundle',label:'Portable bundle',icon:'boxes'},{id:'archive',label:'Private backup',icon:'lock'}].filter(item=>pkg||item.id!=='report')" :key="item.id" type="button" :aria-pressed="mode===item.id" :disabled="!!pending" @click="mode=item.id"><Icon :name="item.icon"/>{{ item.label }}</button></div>
  <p v-if="error" class="ps-notice ps-error" role="alert">{{ error }}</p><p v-if="notice" class="ps-notice" role="status"><Icon name="check"/>{{ notice }}</p>
  <template v-if="mode==='report'">
    <header class="ps-heading"><div><span class="ps-eyebrow">READY FOR THE ISSUE</span><h3>A clear account of what you found.</h3><p>Recorded environments, manual outcomes, and evidence in editable GitHub Markdown.</p></div><button class="ps-primary" type="button" :disabled="!!pending||!markdown" @click="copy"><Icon name="copy"/>{{pending==='copy'?'Copying…':'Copy Markdown'}}</button></header>
    <div class="ps-toolbar"><label>Sessions<select v-model="sessionId" :disabled="!!pending"><option value="">All sessions</option><option v-for="session in pkg.sessions" :key="session.id" :value="session.id">{{session.name}}</option></select></label><label class="ps-check"><input v-model="includeNotes" :disabled="!!pending" type="checkbox"/>Include private package notes</label><button type="button" class="ps-link" :aria-pressed="raw" @click="raw=!raw">{{raw?'Read preview':'Raw Markdown'}}</button></div>
    <p class="ps-hint">Review before sharing. Case text and evidence descriptions are included; credentials are never requested here.</p><p v-if="raw" class="ps-hint">Edits apply to this copied Markdown. Bundle exports generate a fresh report from the saved package.</p>
    <div v-if="reportStale" class="ps-notice"><span>The saved package or report options changed. Your Markdown edits are still here.</span><button type="button" :disabled="!!pending" @click="report">Regenerate report</button></div><div class="ps-report"><p v-if="pending==='report'&&!markdown" class="ps-hint">Preparing your report…</p><textarea v-else-if="raw" v-model="markdown" @input="reportDirty=true" rows="24" aria-label="Report Markdown" spellcheck="false"/><Markdown v-else :content="markdown"/></div>
  </template>
  <template v-else>
    <header class="ps-heading"><div><span class="ps-eyebrow">{{mode==='bundle'?'TAKE THE INVESTIGATION WITH YOU':'YOUR PRIVATE ARCHIVE'}}</span><h3>{{mode==='bundle'?'A plan someone else can repeat.':'Local first. Backed up on your terms.'}}</h3><p>{{mode==='bundle'?'Open a shared investigation here. Imports create a separate copy and never execute anything.':'Save a portable package to your private GitHub repository. Credentials stay in your existing GitHub connection.'}}</p></div><Icon :name="mode==='bundle'?'boxes':'lock'"/></header>
    <section v-if="pkg" class="ps-inclusions"><h4>Choose what travels with this package</h4><p>The plan, frozen sessions, and evidence metadata are included. Large attachments are optional.</p><label class="ps-check"><input v-model="includeNotes" type="checkbox" :disabled="!!pending"/>Include private package notes</label><div v-if="artifacts.length" class="ps-artifacts"><label v-for="artifact in artifacts" :key="artifact.name" class="ps-artifact"><input v-model="artifactNames" :value="artifact.name" :disabled="!!pending||artifact.omitted" type="checkbox"/><span><strong>{{artifact.label}}</strong><small>{{artifact.session}} · {{artifact.kind==='cache-snapshot'?'SQL database':'Activity log'}}{{artifact.omitted?' · file not included in imported bundle':''}}</small></span><span>{{packageBytes(artifact.bytes)}}</span></label></div><p v-else class="ps-hint">No copied attachments in this package yet. Attach evidence during an active session.</p><p class="ps-hint">Selected attachments: {{packageBytes(selectedBytes)}}. Logs and databases can contain workload data; inspect them before sharing.</p></section>
    <div v-if="mode==='bundle'" class="ps-bundle-actions"><button v-if="pkg" type="button" class="ps-primary" :disabled="!!pending" @click="exportBundle"><Icon name="download"/>{{pending==='export'?'Exporting…':'Export package & report'}}</button><button type="button" :disabled="!!pending" @click="fileInput.click()"><Icon name="upload"/>Import a package…</button><input ref="fileInput" type="file" accept=".json,application/json" hidden @change="previewImport"/></div>
    <section v-else class="ps-archive"><div class="ps-archive-label"><h4>Archive repository</h4><button type="button" class="ps-link" @click="connect">Manage GitHub connection <Icon name="arrow"/></button></div><label>Private repository<input v-model="repository" placeholder="your-account/runway-issue-packages" autocomplete="off" :disabled="!!pending"/></label><p class="ps-hint">Runway checks that this repository is private. Backup updates only this package’s archive file and refuses conflicting changes.</p><div class="ps-actions"><button v-if="pkg" type="button" class="ps-primary" :disabled="!!pending||!repository.trim()" @click="inspectArchive"><Icon name="lock"/>{{pending==='inspect'?'Checking repository…':'Review backup'}}</button><button type="button" :disabled="!!pending||!repository.trim()" @click="listArchive"><Icon name="folder"/>Browse saved packages</button><button type="button" class="ps-link" :disabled="!!pending" @click="createRepo=!createRepo">Create private repository…</button></div>
      <div v-if="createRepo" class="ps-review"><h4>Create a dedicated private archive</h4><p>Creates an empty repository in your GitHub account. This does not upload your package yet.</p><label>Repository name<input v-model="newRepo" maxlength="100" :disabled="!!pending"/></label><Confirm title="Create a private GitHub repository?" :message="`Creates ${newRepo.trim()||'a repository'} in your account. Your package is uploaded only after a separate backup review.`" :busy="!!pending" :disabled="!newRepo.trim()" button-label="Create private repository" @confirm="makeRepo" @cancel="createRepo=false"/></div>
      <div v-if="archiveReview" class="ps-review"><h4>{{archiveReview.exists?'Update this package’s backup':'Save the first backup'}}</h4><p>{{archiveReview.repository}} · {{packageBytes(archiveReview.bytes)}} · {{includeNotes?'Private notes included':'Private notes excluded'}} · {{artifactNames.length}} attachments</p><p class="ps-hint">{{archiveReview.exists?'The current remote revision was checked. If it changes, Runway will stop and ask you to review again.':'A new package file will be added. Other repository files remain unchanged.'}}</p><button type="button" class="ps-primary" :disabled="!!pending" @click="backup"><Icon name="upload"/>{{pending==='backup'?'Saving backup…':'Save private backup'}}</button></div>
      <p v-if="archiveResult" class="ps-hint">Last saved {{packageDate(archiveResult.savedAt,true)}} · {{archiveResult.path}}</p>
      <div v-if="archives.length" class="ps-remote-list"><h4>Saved packages</h4><div v-for="item in archives" :key="item.id"><span><strong>{{item.name||item.id}}</strong><small>{{item.path}}</small></span><button type="button" :disabled="!!pending" @click="loadArchive(item)">Review import <Icon name="arrow"/></button></div></div>
    </section>
  </template>
  <div v-if="preview" class="ps-import-review"><h3>Import “{{preview.title}}”?</h3><div class="ps-import-stats"><span><strong>{{preview.cases}}</strong> cases</span><span><strong>{{preview.sessions}}</strong> sessions</span><span><strong>{{preview.artifacts}}</strong> attachments</span><span>{{packageBytes(preview.bytes)}}</span></div><p v-if="preview.issueUrl" class="ps-hint">Issue: {{preview.issueUrl}}</p><p v-if="preview.fixUrl" class="ps-hint">Fix: {{preview.fixTitle||preview.fixUrl}}<template v-if="preview.fixTitle"> · {{preview.fixUrl}}</template></p><p v-for="(warning,index) in preview.warnings" :key="index" class="ps-hint">{{warning}}</p><Confirm title="Add this package to your library?" message="Creates a new local copy. Preserved sessions are read-only. Importing never runs tests or connects to a cluster." :busy="!!pending" button-label="Import package" @confirm="importBundle" @cancel="preview=null;bundle=null"/></div>
</div>
</template>
<style scoped>
.package-sharing{min-width:0;color:var(--runway-ink)}.package-sharing svg{width:17px;height:17px;flex-shrink:0}.package-sharing button{font:inherit;font-size:12px;display:inline-flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;border:1px solid var(--runway-border);border-radius:8px;background:var(--runway-raised);color:var(--runway-ink);padding:10px 14px;font-weight:550}.package-sharing button:disabled{opacity:.45;cursor:not-allowed}.package-sharing :focus-visible{outline:2px solid var(--runway-accent);outline-offset:3px}.package-sharing .ps-primary{background:var(--runway-accent);color:var(--runway-soft);border-color:var(--runway-accent)}.package-sharing .ps-link{background:none;border:0;padding:6px;color:var(--runway-accent)}.ps-tabs{display:flex;gap:6px;border-bottom:1px solid var(--runway-border);padding-bottom:18px;margin-bottom:26px;flex-wrap:wrap}.ps-tabs button{background:none;border-color:transparent;color:var(--runway-muted)}.ps-tabs button[aria-pressed=true]{background:var(--runway-accent-soft);border-color:var(--runway-border);color:var(--runway-accent)}.ps-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin-bottom:22px}.ps-eyebrow{font-size:9px;letter-spacing:.16em;font-weight:650;color:var(--runway-muted)}.ps-heading h3{font-size:23px;letter-spacing:-.03em;line-height:1.3;margin:8px 0}.ps-heading p,.ps-inclusions>p{font-size:12px;line-height:1.7;color:var(--runway-muted);max-width:640px}.ps-heading>svg{width:34px;height:34px;color:var(--runway-accent);margin-top:16px}.ps-heading>button{flex-shrink:0}.ps-toolbar{display:flex;gap:18px;align-items:center;flex-wrap:wrap;padding:15px;background:var(--runway-soft);border:1px solid var(--runway-border);border-radius:10px}.package-sharing label{font-size:12px;font-weight:550;display:grid;gap:7px}.package-sharing input:not([type=checkbox]),.package-sharing select,.package-sharing textarea{background:var(--runway-input);border:1px solid var(--runway-control);color:var(--runway-ink);border-radius:8px;padding:10px 12px;font:inherit;font-weight:400;min-width:0}.package-sharing textarea{width:100%;resize:vertical;line-height:1.7;font-size:12px;font-family:ui-monospace,monospace}.package-sharing .ps-check{display:flex;align-items:center;gap:9px;font-size:11px;font-weight:400}.package-sharing input[type=checkbox]{accent-color:var(--runway-accent);width:15px;height:15px;flex-shrink:0}.ps-hint{font-size:11px;line-height:1.7;color:var(--runway-muted);margin:10px 0}.ps-report{padding:18px 24px;border:1px solid var(--runway-border);border-radius:13px;margin-top:18px;max-height:740px;overflow:auto;overscroll-behavior:contain;background:var(--runway-soft)}.ps-inclusions{border:1px solid var(--runway-border);background:var(--runway-soft);border-radius:12px;padding:20px;margin:20px 0}.ps-inclusions h4,.ps-archive h4{font-size:14px;font-weight:600}.ps-inclusions>.ps-check{margin:16px 0}.ps-artifacts{border-top:1px solid var(--runway-border)}.package-sharing .ps-artifact{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid var(--runway-border);font-size:11px}.ps-artifact>span:nth-child(2){flex:1;min-width:0}.ps-artifact strong,.ps-remote-list strong{display:block;overflow-wrap:anywhere;font-size:12px}.ps-artifact small,.ps-remote-list small{display:block;font-size:10px;font-weight:400;color:var(--runway-muted);margin-top:3px;overflow-wrap:anywhere}.ps-artifact>span:last-child{color:var(--runway-muted);white-space:nowrap;font-size:10px}.ps-bundle-actions,.ps-actions{display:flex;gap:10px;flex-wrap:wrap}.ps-archive-label{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;gap:12px;flex-wrap:wrap}.ps-archive>label{max-width:600px}.ps-review,.ps-import-review{margin-top:20px;border:1px solid var(--runway-border);border-radius:12px;padding:20px;background:var(--runway-soft)}.ps-review>p{font-size:12px;line-height:1.7;margin:10px 0}.ps-review>label{max-width:500px;margin:16px 0}.ps-import-review h3{font-size:18px;font-weight:600;margin-bottom:15px}.ps-import-stats{display:flex;gap:20px;flex-wrap:wrap;font-size:11px;color:var(--runway-muted);margin-bottom:18px}.ps-import-stats strong{font-size:17px;color:var(--runway-ink);margin-right:4px}.ps-notice{display:flex;gap:10px;padding:13px 16px;background:var(--runway-accent-soft);border:1px solid var(--runway-border);border-radius:9px;font-size:12px;line-height:1.6;color:var(--runway-accent);margin-bottom:20px;overflow-wrap:anywhere}.ps-error{color:var(--runway-error)}.ps-remote-list{margin-top:24px}.ps-remote-list>div{display:flex;gap:15px;align-items:center;padding:13px 0;border-bottom:1px solid var(--runway-border)}.ps-remote-list>div>span{flex:1;min-width:0}.ps-remote-list h4{margin-bottom:10px}@media(max-width:850px){.ps-heading{flex-direction:column}.ps-heading>svg{display:none}.ps-report{padding:10px 16px}.ps-remote-list>div{align-items:flex-start;flex-direction:column}}
</style>
